extractor:
function extract(raw, memory) {
  var TICK_MS = 33;
  var DEFAULT_STEP = 180 * TICK_MS / 1000;
  function wrap180(x) { return ((x + 180) % 360 + 360) % 360 - 180; }
  function mod360(x) { return (x % 360 + 360) % 360; }
  function r1(x) { return Math.round(x * 10) / 10; }
  function isRed(t) {
    if (t === undefined || t === null) return false;
    var n = typeof t === 'number' ? t : parseInt(String(t).replace('#', '').replace('0x', ''), 16);
    if (isNaN(n)) return false;
    var r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
    return r >= 176 && g < 112 && b < 112;
  }
  var objs = (raw && raw.objects) || [];
  var ring = null, bar = null, dots = [], texts = [], rest = [];
  var i, o, nm;
  for (i = 0; i < objs.length; i++) {
    o = objs[i];
    if (!o) continue;
    if (o.text !== undefined && o.text !== null) { texts.push(o); continue; }
    nm = ((o.tex || '') + ' ' + (o.frame || '') + ' ' + (o.name || '')).toLowerCase();
    if (!ring && nm.indexOf('ring') >= 0) ring = o;
    else if (!bar && (nm.indexOf('bar') >= 0 || nm.indexOf('needle') >= 0 || nm.indexOf('pointer') >= 0)) bar = o;
    else if (nm.indexOf('ball') >= 0 || nm.indexOf('dot') >= 0 || nm.indexOf('target') >= 0) dots.push(o);
    else rest.push(o);
  }
  var others = [], needDot = dots.length === 0;
  for (i = 0; i < rest.length; i++) {
    o = rest[i];
    var w = o.w || 0, h = o.h || 0;
    if (!ring && w >= 200 && Math.abs(w - h) < 0.2 * w) ring = o;
    else if (!bar && h > 0 && w >= 4 * h) bar = o;
    else if (needDot && w > 0 && w <= 120 && Math.abs(w - h) < 0.3 * w) dots.push(o);
    else others.push(o);
  }
  var cx = ring ? ring.x : (bar ? bar.x : 0), cy = ring ? ring.y : (bar ? bar.y : 0);
  var barA = bar ? (bar.a || 0) : 0;
  if (!memory.init) {
    memory.init = true; memory.dir = 1; memory.step = DEFAULT_STEP; memory.lastStep = DEFAULT_STEP;
    memory.pops = 0; memory.still = 0; memory.over = false; memory.prevA = null; memory.prevDot = null; memory.dotMovedLast = false;
  }
  var delta = (memory.prevA === null || !bar) ? 0 : wrap180(barA - memory.prevA);
  var moving = Math.abs(delta) > 0.3;
  memory.still = (moving || memory.prevA === null) ? 0 : memory.still + 1;
  var over = !bar || isRed(bar.tint) || memory.still >= 8;
  if (memory.over && !over) {
    memory.pops = 0; memory.dir = 1; memory.step = DEFAULT_STEP; memory.lastStep = DEFAULT_STEP;
    memory.prevDot = null; memory.dotMovedLast = false;
  }
  var dot = null, best = 1e9;
  for (i = 0; i < dots.length; i++) {
    var da = Math.atan2(dots[i].y - cy, dots[i].x - cx) * 180 / Math.PI;
    var gg = mod360((da - barA) * memory.dir);
    if (gg > 330) gg -= 360;
    if (gg < best) { best = gg; dot = dots[i]; }
  }
  var dotMoved = !!(dot && memory.prevDot && Math.abs(dot.x - memory.prevDot.x) + Math.abs(dot.y - memory.prevDot.y) > 3);
  var clearMove = moving && Math.abs(delta) < 60 && Math.abs(delta) >= 0.6 * memory.lastStep;
  if (!over && !memory.over && dotMoved && !memory.dotMovedLast) {
    memory.pops++;
    memory.dir = clearMove ? (delta > 0 ? 1 : -1) : -memory.dir;
  } else if (!over && moving && Math.abs(delta) < 60) {
    memory.dir = delta > 0 ? 1 : -1;
    if (!dotMoved) { memory.lastStep = Math.abs(delta); memory.step = 0.5 * memory.step + 0.5 * memory.lastStep; }
  }
  var dir = memory.dir;
  var step = Math.max(memory.step, memory.lastStep);
  var dotA = 0, dotDist = 0, gap = 0, hitTol = 8;
  if (dot) {
    dotA = Math.atan2(dot.y - cy, dot.x - cx) * 180 / Math.PI;
    dotDist = Math.sqrt((dot.x - cx) * (dot.x - cx) + (dot.y - cy) * (dot.y - cy));
    gap = mod360((dotA - barA) * dir);
    if (gap > 330) gap -= 360;
    if (dotDist > 1) hitTol = Math.atan2((dot.w || 50) / 2, dotDist) * 180 / Math.PI;
    hitTol = Math.max(3, Math.min(20, hitTol));
  }
  var gapNext = gap - step;
  var onDot = !!dot && Math.abs(gap) <= hitTol;
  var tapOutcome = over ? 'none' : (!dot ? 'gameOver' : (dotMoved ? 'uncertain' : (onDot ? 'pop' : 'gameOver')));
  var waitOutcome = over ? 'none' : (!dot ? 'safe' : (gapNext < -hitTol ? 'gameOver' : (gapNext < 0 ? 'crossesDot' : 'safe')));
  var score = null, hud = [];
  for (i = 0; i < texts.length; i++) {
    var s = String(texts[i].text).trim();
    if (hud.length < 3) hud.push(s.slice(0, 24));
    if (score === null && /^[0-9]+$/.test(s)) score = parseInt(s, 10);
  }
  var unknown = [];
  for (i = 0; i < others.length && unknown.length < 4; i++) {
    o = others[i];
    unknown.push({ tex: String(o.tex || o.type || '?'), x: Math.round(o.x || 0), y: Math.round(o.y || 0), w: o.w || 0, h: o.h || 0,
      distFromCentre: Math.round(Math.sqrt((o.x - cx) * (o.x - cx) + (o.y - cy) * (o.y - cy))),
      angleDeg: Math.round(Math.atan2(o.y - cy, o.x - cx) * 180 / Math.PI) });
  }
  if (bar) memory.prevA = barA;
  memory.prevDot = dot ? { x: dot.x, y: dot.y } : null;
  memory.dotMovedLast = dotMoved;
  memory.over = over;
  var state = {
    gameOver: over,
    pops: memory.pops,
    barMoving: moving,
    dir: dir > 0 ? 'clockwise' : 'counterclockwise',
    barAngleDeg: r1(barA),
    dotAngleDeg: dot ? r1(dotA) : null,
    dotVisible: !!dot,
    dotMoving: dotMoved,
    stepDeg: r1(step),
    gapDeg: r1(gap),
    gapNextDeg: r1(gapNext),
    hitTolDeg: r1(hitTol),
    onDot: onDot,
    ticksToDot: step > 0 ? r1(gap / step) : null,
    tapOutcome: tapOutcome,
    waitOutcome: waitOutcome
  };
  if (dots.length > 1) state.dotCount = dots.length;
  if (score !== null) state.score = score;
  if (hud.length) state.hudText = hud;
  if (unknown.length) state.unknown = unknown;
  return state;
}

teacher:
function teach(state) {
  if (!state || state.gameOver) return 'wait';
  if (state.tapOutcome === 'pop' && state.waitOutcome !== 'safe') return 'tap';
  return 'wait';
}
